// 密钥管理：敏感值从环境变量取，绝不写进代码或配置文件；日志中掩码
const env = { DB_PASSWORD: "s3cr3t-from-env", API_KEY: "" };

function requireSecret(name) {
  const v = env[name];
  if (!v) throw new Error(`缺少环境变量 ${name}`);
  return "***" + v.slice(-3); // 只展示掩码，绝不打印明文
}

try {
  console.log("DB_PASSWORD", requireSecret("DB_PASSWORD"));
  console.log("API_KEY", requireSecret("API_KEY"));
